"  const getYAxisTicks = (maxVal) => {
    if (!maxVal || maxVal < 0) {
      return [0, 200];
    }
    let step = 200;
    if (maxVal > 1000) {
      const rawStep = maxVal / 5;
      step = Math.ceil(rawStep / 200) * 200;
    }
    const ticksCount = Math.ceil(maxVal / step);
    const ticks = [];
    for (let i = 0; i <= ticksCount; i++) {
      ticks.push(i * step);
    }
    if (ticks.length < 2) {
      return [0, 200];
    }
    return ticks;
  };

  const getYCoordinate = (val, ticks) => {
    const maxTickVal = ticks[ticks.length - 1] || 200;
    if (val <= 0) return 100;
    if (val >= maxTickVal) return 0;
    const pct = (val / maxTickVal) * 100;
    return 100 - pct;
  };"

