"  const getYAxisTicks = (maxVal) => {
    const ticks = [0];
    let val = 10;
    const limit = Math.max(1000, maxVal);
    while (val <= limit * 10) {
      ticks.push(val);
      if (val > limit) break;
      val *= 10;
    }
    return ticks;
  };

  const getYCoordinate = (val, ticks) => {
    if (val <= 0) return 100;
    const numIntervals = ticks.length - 1;
    let intervalIdx = 0;
    for (let i = 0; i < numIntervals; i++) {
      if (val <= ticks[i + 1]) {
        intervalIdx = i;
        break;
      }
    }
    if (val > ticks[ticks.length - 1]) {
      intervalIdx = numIntervals - 1;
    }
    const startVal = ticks[intervalIdx];
    const endVal = ticks[intervalIdx + 1];
    let fraction = 0;
    if (intervalIdx === 0) {
      fraction = val / (endVal || 10);
    } else {
      const logStart = Math.log10(startVal || 1);
      const logEnd = Math.log10(endVal || 10);
      const logVal = Math.log10(val || 1);
      fraction = (logVal - logStart) / (logEnd - logStart);
    }
    const pct = ((intervalIdx + fraction) / numIntervals) * 100;
    const boundPct = Math.min(100, Math.max(0, pct));
    return 100 - boundPct;
  };"
